from contextlib import contextmanager

@contextmanager
def tag(name):
    print(f"<{name}>")       # setup
    try:
        yield                 # the with-block runs here
    finally:
        print(f"</{name}>")   # cleanup: always runs

with tag("p"):
    print("hello")

